fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    fn prefix_sum(k: i16) -> i16 {
        if k <= 0 {
            return 0;
        }
        if k % 2 == 0 {
            k / 2
        } else {
            -(k + 1) / 2
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            let l = l as i16;
            let r = r as i16;
            let ans = prefix_sum(r) - prefix_sum(l - 1);
            ans as i8
        })
        .collect()
}